const items = $input.all();
for (const item of items) {
  const content = item.json.websiteContent || '';
  item.json.websiteContent = content.substring(0, 2000);
}
return items;

const items = $input.all();
for (const item of items) {
  try {
    const aiResponse = item.json.text || item.json.message?.content || '{}';
    const parsed = JSON.parse(aiResponse);
    item.json.aiScore = parsed.score || 0;
    item.json.aiReasoning = parsed.reasoning || '';
    item.json.aiCategory = parsed.category || 'cold';
  } catch (e) {
    item.json.aiScore = 0;
    item.json.aiReasoning = 'Failed to parse AI response';
    item.json.aiCategory = 'cold';
  }
}
return items;

const items = $input.all();
for (const item of items) {
  try {
    const aiResponse = item.json.text || item.json.message?.content || '{}';
    const parsed = JSON.parse(aiResponse);
    item.json.emailSubject = parsed.subject || 'Quick question';
    item.json.emailBody = parsed.body || '';
    item.json.followUp1Subject = parsed.followUp1Subject || '';
    item.json.followUp1Body = parsed.followUp1Body || '';
    item.json.followUp2Subject = parsed.followUp2Subject || '';
    item.json.followUp2Body = parsed.followUp2Body || '';
  } catch (e) {
    item.json.emailSubject = 'Quick question';
    item.json.emailBody = 'Failed to generate personalized email.';
    item.json.followUp1Subject = '';
    item.json.followUp1Body = '';
    item.json.followUp2Subject = '';
    item.json.followUp2Body = '';
  }
}
return items;
